// Decides where a request to the OLD blog host (blog.accredian.com) goes. Pure function: no Next.js, no I/O,
// so it can be unit-tested and reused by migration/check-redirects.mjs.
//
// Returns { location, status } for a redirect, or null when the old URL has no equivalent (the caller
// answers 404). `location` is always the FINAL absolute URL on https://accredian.com/blog/..., so every
// old URL is exactly one hop.
//
// What it adds on top of mapLegacyBlogPath (structure only) is knowledge of what actually exists, from
// redirect-data.json (generated by migration/generate-old-blog-redirects.mjs):
//   - only the 1,108 real post slugs redirect (an unknown /<slug> is a 404, as before)
//   - only categories / authors / spotlight keys that have content redirect
//   - an empty spotlight key goes to the spotlight index; empty categories stay 404
import { mapLegacyBlogPath } from "./legacy-paths.js";

export const NEW_ORIGIN = "https://accredian.com";
export const REDIRECT_STATUS = 301;

// /blog/<x> destinations that are fixed pages, not posts
const FIXED_PAGES = new Set(["articles", "search", "testimonials", "spotlight", "success-stories"]);

const setsCache = new WeakMap();
function setsFor(data) {
  let sets = setsCache.get(data);
  if (!sets) {
    sets = {
      posts: new Set(data.postSlugs),
      categories: new Set(data.categorySlugs),
      spotlight: new Set(data.spotlightKeys),
      emptySpotlight: new Set(data.emptySpotlightKeys),
      authors: new Set(data.authorSlugs),
    };
    setsCache.set(data, sets);
  }
  return sets;
}

// Final destination for a mapped path, or null when its target doesn't exist.
function validate(destination, sets) {
  const parts = destination.split("/").filter(Boolean); // ["blog", ...]
  if (parts.length === 1) return destination; // /blog
  const [, second, third] = parts;

  if (parts.length === 2) {
    return FIXED_PAGES.has(second) || sets.posts.has(second) ? destination : null;
  }
  if (parts.length === 3) {
    if (second === "category") return sets.categories.has(third) ? destination : null;
    if (second === "author") return sets.authors.has(third) ? destination : null;
    if (second === "success-stories") return third === "ds" || third === "pm" ? destination : null;
    if (second === "spotlight") {
      if (sets.spotlight.has(third)) return destination;
      return sets.emptySpotlight.has(third) ? "/blog/spotlight" : null;
    }
  }
  return null;
}

const pageNumber = (value) => (/^[1-9]\d{0,5}$/.test(value ?? "") ? Number(value) : null);

// Old paginated listings used ?page=N; the new site uses /page/N (N >= 2).
const isPaginatedDestination = (destination, sourcePath) =>
  (sourcePath === "/blog" && destination === "/blog/articles") ||
  /^\/blog\/(category|spotlight)\/[^/]+$/.test(destination);

/**
 * @param {{ pathname: string, searchParams: URLSearchParams }} request
 * @param {object} data parsed redirect-data.json
 * @param {{ enableAccredianSpotlight?: boolean }} [options]
 */
export function resolveLegacyRedirect({ pathname, searchParams }, data, options = {}) {
  const sourcePath = pathname.replace(/\/+$/, "") || "/"; // /x and /x/ are the same old URL

  // The NESTED WordPress taxonomy (/category/accredian-spotlight/<group>/<leaf>) is held back until Search
  // Console has been reviewed; until enabled these answer 404. (The two roots, /category/accredian-spotlight
  // and /category/accredian-pm-spotlight, are ordinary single-segment categories the old site serves today,
  // so they redirect normally.)
  if (/^\/category\/accredian(-pm)?-spotlight\//.test(sourcePath)) {
    if (!options.enableAccredianSpotlight) return null;
    const held = data.heldAccredianSpotlight[sourcePath];
    return held ? { location: NEW_ORIGIN + held, status: REDIRECT_STATUS } : null;
  }

  // Blog URLs live in the main site's sitemap (accredian.com/blog/sitemap.xml does not exist).
  if (sourcePath === "/sitemap.xml") return { location: `${NEW_ORIGIN}/sitemap.xml`, status: REDIRECT_STATUS };

  const mapped = mapLegacyBlogPath(sourcePath);
  if (!mapped) return null;
  let destination = validate(mapped, setsFor(data));
  if (!destination) return null;

  const page = pageNumber(searchParams.get("page"));
  if (page && page > 1 && isPaginatedDestination(destination, sourcePath)) destination += `/page/${page}`;

  // Search keeps its query (q); every other old URL drops its query string (utm, ?page=1, ...).
  const search = destination === "/blog/search" && searchParams.get("q") ? `?q=${encodeURIComponent(searchParams.get("q"))}` : "";

  return { location: `${NEW_ORIGIN}${destination}${search}`, status: REDIRECT_STATUS };
}
